585: void IndexedBlockBuffer::parse(Buffer& buffer)
586: {
587:     // Modifies buffer to use a loader that stores offsets and data in
588:     // m_tokens_list. Original loader restored at data_collector destruction.
589:     BufferDataCollector data_collector(&buffer, &m_tokens_list);
590: 
591:     size_t values = m_rows * (m_property_names.size() + 1);
592:     m_tokens_list.reserve(values);
593: 
594:     if (buffer.size() == 0) {
595:         if (!buffer.load()) {
596:             throw read_exception(buffer,
597:                                  "Unexpected EOF in indexed block scan.");
598:         }
599:     }
600:     m_tokens_list.appendBufferData(buffer.data());
601: 
602:     for (std::size_t ix = 0; ix < values; ix++) {
603:         // TODO: Another boost in performance can be had by avoiding the
604:         // function call overhead for value and whitespace, but simplying
605:         // marking the functions as inline doesn't seem to do the trick.
606:         whitespace(buffer);
607:         value(buffer);
608:     }
609:     whitespace(buffer);
610: }
611: 
612: /**
613:  * This function is measurably faster than strtol.
614:  *
615:  * The main reason for this is probably that it does not deal with alternate
616:  * bases for the integer.
617:  */
618: static long int simple_strtol(const char* ptr, const char* end)
619: {
620:     long int value = 0;
621:     long int sign = 1;
622: 
623:     while (ptr < end) {
624:         switch (*ptr) {
625:         case '0':
626:         case '1':
627:         case '2':
628:         case '3':
629:         case '4':
630:         case '5':
631:         case '6':
632:         case '7':
633:         case '8':
634:         case '9':
635:             value = value * 10 + *ptr - '0';
636:             break;
637:         case '-':
638:             if (sign == -1 || value) {
639:                 throw std::invalid_argument("Unexpected '-' in integer.");
640:             }
641:             sign = -1;
642:             break;
643:         default:
644:             throw std::invalid_argument("Unexpected character in integer.");
645:         }
646:         ++ptr;
647:     }
648:     return value * sign;
649: }
