651: IndexedBlock* IndexedBlockBuffer::getIndexedBlock()
652: {
653:     auto* iblock = new IndexedBlock(getName());
654: 
655:     std::vector<std::string>::const_iterator iter = m_property_names.begin();
656: 
657:     // Indexed blocks have row indexes explicitly mixed in as the first
658:     // value of each row. This is why a) prop_indx starts at 1, b)
659:     // col_count is prop_count + 1 instead of prop_count.
660:     //
661:     size_t prop_count = m_property_names.size();
662:     size_t col_count = prop_count + 1;
663:     size_t value_count = col_count * m_rows;
664:     boost::dynamic_bitset<>* is_null = nullptr;
665:     for (int prop_indx = 1; iter != m_property_names.end();
666:          ++iter, ++prop_indx) {
667:         char type = (*iter)[0];
668:         is_null = nullptr;
669:         const char* data;
670:         size_t len;
671:         switch (type) {
672:         case 'b': {
673:             std::vector<BoolProperty> bvalues;
674:             bvalues.reserve(m_rows);
675:             for (size_t ix = prop_indx; ix < value_count; ix += col_count) {
676:                 getData(ix, &data, &len);
677:                 if (data[0] == '<' && data[1] == '>') {
678:                     if (is_null == nullptr) {
679:                         is_null = new boost::dynamic_bitset<>(m_rows);
680:                     }
681:                     is_null->set(bvalues.size());
682:                     bvalues.push_back(false);
683:                 } else if (data[0] == '1') {
684:                     bvalues.push_back(true);
685:                 } else if (data[0] == '0') {
686:                     bvalues.push_back(false);
687:                 } else {
688:                     throw std::out_of_range("Bogus bool.");
689:                 }
690:             }
691:             std::shared_ptr<IndexedBoolProperty> ibp(
692:                 new IndexedBoolProperty(bvalues, is_null));
693:             iblock->setBoolProperty(*iter, ibp);
694:         } break;
695:         case 'i': {
696:             std::vector<int> ivalues;
697:             ivalues.reserve(m_rows);
698:             for (size_t ix = prop_indx; ix < value_count; ix += col_count) {
699:                 getData(ix, &data, &len);
700:                 if (data[0] == '<' && data[1] == '>') {
701:                     if (is_null == nullptr) {
702:                         is_null = new boost::dynamic_bitset<>(m_rows);
703:                     }
704:                     is_null->set(ivalues.size());
705:                     ivalues.push_back(0);
706:                 } else {
707:                     long int value = simple_strtol(data, data + len);
708:                     ivalues.push_back(value);
709:                 }
710:             }
711:             std::shared_ptr<IndexedIntProperty> iip(
712:                 new IndexedIntProperty(ivalues, is_null));
713:             iblock->setIntProperty(*iter, iip);
714:         } break;
715:         case 'r': {
716:             std::vector<double> dvalues;
717:             dvalues.reserve(m_rows);
718:             for (size_t ix = prop_indx; ix < value_count; ix += col_count) {
719:                 getData(ix, &data, &len);
720:                 if (data[0] == '<' && data[1] == '>') {
721:                     if (is_null == nullptr) {
722:                         is_null = new boost::dynamic_bitset<>(m_rows);
723:                     }
724:                     is_null->set(dvalues.size());
725:                     dvalues.push_back(0);
726:                 } else {
727:                     double value = 0;
728:                     const char* end = data + len;
729:                     if (!qi::parse(data, end, qi::double_, value) ||
730:                         data != end) {
731:                         throw std::invalid_argument("Bad floating point "
732:                                                     "representation.");
733:                     }
734:                     dvalues.push_back(value);
735:                 }
736:             }
737:             std::shared_ptr<IndexedRealProperty> irp(
738:                 new IndexedRealProperty(dvalues, is_null));
739:             iblock->setRealProperty(*iter, irp);
740:         } break;
741:         case 's': {
742:             std::vector<std::string> svalues;
743:             svalues.reserve(m_rows);
744:             for (size_t ix = prop_indx; ix < value_count; ix += col_count) {
745:                 getData(ix, &data, &len);
746:                 if (data[0] == '<' && data[1] == '>') {
747:                     if (is_null == nullptr) {
748:                         is_null = new boost::dynamic_bitset<>(m_rows);
749:                     }
750:                     is_null->set(svalues.size());
751:                     svalues.emplace_back();
752:                 } else {
753:                     if (data[0] != '"') { // Check for quote wrapping
754:                         svalues.emplace_back(data, len);
755:                     } else { // During parsing we check for full quote wrapping
756:                         auto rval = std::string(data + 1, len - 2);
757:                         remove_escape_characters(rval);
758:                         svalues.emplace_back(rval);
759:                     }
760:                 }
761:             }
762:             std::shared_ptr<IndexedStringProperty> isp(
763:                 new IndexedStringProperty(svalues, is_null));
764:             iblock->setStringProperty(*iter, isp);
765:         } break;
766:         }
767:     }
768:     return iblock;
769: }
